def test_report_failure_neutral_header_when_not_a_failure(tmp_path, monkeypatch, capsys):
    monkeypatch.setattr("localm.config.home_dir", lambda: tmp_path)
    bugreport.report_failure(
        summary="user filed this", as_failure=False, interactive=False)
