def test_auto_send_upload_failure_is_never_reported_as_success(tmp_path, monkeypatch, capsys):
    monkeypatch.setattr("localm.config.home_dir", lambda: tmp_path)
    monkeypatch.setattr("localm.config.load_config", lambda: {
        "bugreport_upload_url": "https://proxy.example/"})

    def _boom(*a, **k):
        raise bugreport.LocalmError("upload failed", reason="502 from proxy")
    monkeypatch.setattr(bugreport, "upload_report", _boom)
    bugreport.report_failure(summary="bug", interactive=False, auto_send=True)
    out = " ".join(capsys.readouterr().out.split())   # collapse rich's line-wrapping
    assert "Sent to the maintainer" not in out
    assert "Could not send it" in out
    # The email fallback is offered (now naming the maintainer address).
    assert "email it to" in out and bugreport.MAINTAINER_EMAIL in out


# --------------------------- process-wide net ----------------------------- #

def test_thread_excepthook_reports_without_prompting(monkeypatch):
    calls = []
    monkeypatch.setattr(bugreport, "report_failure", lambda **k: calls.append(k))
    args = types.SimpleNamespace(
        exc_type=ValueError, exc_value=ValueError("worker boom"),
        exc_traceback=None, thread=types.SimpleNamespace(name="jobs-runner"))
    bugreport._handle_thread_exception(args)
    assert len(calls) == 1
    assert calls[0]["interactive"] is False
    assert calls[0]["context"]["thread"] == "jobs-runner"


def test_thread_excepthook_ignores_systemexit(monkeypatch):
    calls = []
    monkeypatch.setattr(bugreport, "report_failure", lambda **k: calls.append(k))
    args = types.SimpleNamespace(
        exc_type=SystemExit, exc_value=SystemExit(0),
        exc_traceback=None, thread=types.SimpleNamespace(name="t"))
    bugreport._handle_thread_exception(args)
    assert calls == []


def test_main_excepthook_reports_real_error(monkeypatch):
    calls = []
    monkeypatch.setattr(bugreport, "report_failure", lambda **k: calls.append(k))
    bugreport._handle_main_exception(ValueError, ValueError("boom"), None)
    assert len(calls) == 1
    assert "unexpected error" in calls[0]["summary"]


def test_main_excepthook_uses_localmerror_fields(monkeypatch):
    calls = []
    monkeypatch.setattr(bugreport, "report_failure", lambda **k: calls.append(k))
    err = bugreport.LocalmError("backend dead", reason="no driver", context={"x": 1})
    bugreport._handle_main_exception(bugreport.LocalmError, err, None)
    assert calls[0]["summary"] == "backend dead"
    assert calls[0]["reason"] == "no driver"
    assert calls[0]["context"] == {"x": 1}


def test_main_excepthook_keyboardinterrupt_does_not_report(monkeypatch):
    calls = []
    monkeypatch.setattr(bugreport, "report_failure", lambda **k: calls.append(k))
    monkeypatch.setattr(sys, "__excepthook__", lambda *a: None)
    bugreport._handle_main_exception(KeyboardInterrupt, KeyboardInterrupt(), None)
    assert calls == []


def test_install_global_handlers_noop_under_pytest(monkeypatch):
    monkeypatch.setattr(bugreport, "_handlers_installed", False)
    # pytest is in sys.modules, so the default (unforced) call is a deliberate no-op.
    assert bugreport.install_global_handlers() is False


def test_install_global_handlers_force_sets_hooks(monkeypatch):
    monkeypatch.setattr(bugreport, "_handlers_installed", False)
    orig_e, orig_t = sys.excepthook, threading.excepthook
    try:
        assert bugreport.install_global_handlers(force=True) is True
        assert sys.excepthook is bugreport._handle_main_exception
        assert threading.excepthook is bugreport._handle_thread_exception
    finally:
        sys.excepthook, threading.excepthook = orig_e, orig_t


# --------------------------- editable file is what's sent ----------------- #

def test_report_failure_sends_edited_file_not_original(tmp_path, monkeypatch):
    """'Edit it before sending' must be true: the email/issue body is read back
    from the (possibly edited) file, not the original generated text."""
    monkeypatch.setattr("localm.config.home_dir", lambda: tmp_path)
    edited = tmp_path / "bug-reports" / "edited.md"

    def fake_save(text, when=None):
        edited.parent.mkdir(parents=True, exist_ok=True)
        edited.write_text("EDITED REPORT BODY", encoding="utf-8")
        return edited
    monkeypatch.setattr(bugreport, "save_report", fake_save)

    opened = []
    bugreport.report_failure(
        summary="bug", interactive=True,
        open_browser=lambda u: opened.append(u), prompt=lambda _t: "2")  # [2] = email
    assert opened
    assert "EDITED REPORT BODY" in unquote(opened[0])   # the edit, not the original


# --------------------------- file permissions ----------------------------- #

@pytest.mark.skipif(os.name != "posix", reason="POSIX file mode bits")
def test_save_report_is_owner_only(tmp_path, monkeypatch):
    monkeypatch.setattr("localm.config.home_dir", lambda: tmp_path)
    path = bugreport.save_report("secretish diagnostics", when="t")
    assert path is not None
    assert stat.S_IMODE(os.stat(path).st_mode) == 0o600


# --------------------------- the bug-report CLI command ------------------- #

def test_bug_report_command_via_cli(tmp_path, monkeypatch):
    monkeypatch.setattr("localm.config.home_dir", lambda: tmp_path)
    from localm.cli import main
    res = CliRunner().invoke(main, ["bug-report", "-m", "my problem"])
    assert res.exit_code == 0, res.output
    assert "Filing a bug report" in res.output
    assert "my problem" in res.output
    assert "Sorry -" not in res.output               # user-initiated, not a crash
    assert list((tmp_path / "bug-reports").glob("*.md"))


def test_bug_report_command_send_flag_uploads_immediately(tmp_path, monkeypatch):
    """`localm bug-report --send` is the fix's whole point: a working, login-free
    send path that a tester in a non-tty shell (or told the exact command by the
    maintainer) can actually run."""
    monkeypatch.setattr("localm.config.home_dir", lambda: tmp_path)
    monkeypatch.setattr("localm.config.load_config", lambda: {
        "bugreport_upload_url": "https://proxy.example/"})
    monkeypatch.setattr(bugreport, "upload_report",
                        lambda *a, **k: {"url": "https://github.com/x/y/issues/3"})
    from localm.cli import main
    res = CliRunner().invoke(main, ["bug-report", "-m", "my problem", "--send"])
    assert res.exit_code == 0, res.output
    assert "Sent to the maintainer" in res.output
    assert "https://github.com/x/y/issues/3" in res.output


class TestRecommendedBackendMatchesInstallPolicy:
    """The report's "Recommended backend" must be the policy the INSTALLER would
    apply, not the blanket "vulkan whenever a GPU exists" detection value.

    A real report (#833) from an NVIDIA-on-Windows box said "Recommended backend:
    vulkan" while that box's policy is cuda (#765) and it was in fact running the
    CUDA runtime. A diagnostics field that contradicts what the installer would
    provision sends triage after the wrong thing."""

    def _diag_with(self, monkeypatch, vendors, platform):
        from localm import hwdetect
        det = hwdetect.Detection(vendors=vendors, recommended="vulkan",
                                 source="test", gpu_names=" ".join(vendors))
        monkeypatch.setattr(hwdetect, "detect", lambda: det)
        monkeypatch.setattr(sys, "platform", platform)
        return bugreport.collect_diagnostics({})

    def test_nvidia_on_windows_reports_cuda_not_vulkan(self, monkeypatch):
        diag = self._diag_with(monkeypatch, ["nvidia"], "win32")
        assert diag["recommended_backend"] == "cuda", (
            "an NVIDIA Windows box reported a backend the installer would not "
            "provision - the #833 triage trap")

    def test_no_gpu_still_reports_cpu(self, monkeypatch):
        diag = self._diag_with(monkeypatch, [], "win32")
        assert diag["recommended_backend"] == "cpu"

    def test_nvidia_on_linux_stays_vulkan(self, monkeypatch):
        """The Linux CUDA build needs a system toolkit localm cannot self-provide,
        so vulkan genuinely IS the policy there - the fix must not overreach."""
        diag = self._diag_with(monkeypatch, ["nvidia"], "linux")
        assert diag["recommended_backend"] == "vulkan"
